<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">Read-only ledger</span><h2>Orders & payments</h2><p>Financial records are displayed for reference only. Use the payment provider for refunds or transaction corrections.</p></div></div>
  <?php if ($sectionData['order']): ?><section class="admin-panel order-detail-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Order #<?= (int) $sectionData['order']['id'] ?></span><h2><?= $this->escape($sectionData['order']['customer_name'] ?: 'Guest customer') ?></h2><p><?= $this->escape($sectionData['order']['customer_email'] ?: 'No account email') ?> · <?= $this->escape(date('M j, Y H:i', strtotime($sectionData['order']['created_at']))) ?></p></div><a class="button button-ghost" href="<?= $this->escape(appUrl('/admin/orders')) ?>">Back to orders</a></div>
    <h3>Items</h3><?php if (!$sectionData['items']): ?><p class="admin-empty">No order items were recorded.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th></tr></thead><tbody><?php foreach ($sectionData['items'] as $item): ?><tr><td><?= $this->escape($item['product_name'] ?: 'Removed product') ?></td><td><?= (int) $item['quantity'] ?></td><td><?= $this->escape($sectionData['order']['currency']) ?> <?= number_format((float) $item['unit_price'], 2) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
    <h3>Payment status</h3><?php if (!$sectionData['payments']): ?><p class="admin-empty">No payment records.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Provider</th><th>Reference</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach ($sectionData['payments'] as $payment): ?><tr><td><?= $this->escape($payment['provider']) ?></td><td><?= $this->escape($payment['provider_reference'] ?: '—') ?></td><td><?= $this->escape($payment['currency']) ?> <?= number_format((float) $payment['amount'], 2) ?></td><td><span class="status-badge status-<?= $this->escape($payment['status']) ?>"><?= $this->escape(ucfirst($payment['status'])) ?></span></td><td><?= $this->escape(date('M j, Y', strtotime($payment['created_at']))) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section><?php endif ?>
  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Transactions</span><h2>Recent orders <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No orders are on record.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach ($sectionData['records'] as $record): ?><tr><td>#<?= (int) $record['id'] ?><small class="table-subtext"><?= $this->escape(ucfirst($record['order_type'])) ?></small></td><td><?= $this->escape($record['customer_name'] ?: 'Guest') ?><small class="table-subtext"><?= $this->escape($record['customer_email'] ?: '') ?></small></td><td><?= (int) $record['item_count'] ?></td><td><?= $this->escape($record['currency']) ?> <?= number_format((float) $record['subtotal'], 2) ?></td><td><span class="status-badge status-<?= $this->escape($record['status']) ?>"><?= $this->escape(ucfirst($record['status'])) ?></span></td><td><?= $this->escape(date('M j, Y', strtotime($record['created_at']))) ?></td><td><a class="admin-icon-link" aria-label="View order <?= (int) $record['id'] ?>" href="<?= $this->escape(appUrl('/admin/orders?id=' . (int) $record['id'])) ?>"><i data-lucide="eye"></i></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section>
</section>
